@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --background: oklch(0.98 0.002 160);
  --foreground: oklch(0.13 0.01 160);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.13 0.01 160);
  --primary: oklch(0.58 0.18 165);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.96 0.005 160);
  --secondary-foreground: oklch(0.25 0.01 160);
  --muted: oklch(0.96 0.003 160);
  --muted-foreground: oklch(0.48 0.012 160);
  --accent: oklch(0.58 0.18 165);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.55 0.2 30);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.9 0.005 160);
  --input: oklch(0.9 0.005 160);
  --ring: oklch(0.58 0.18 165);
  --success: oklch(0.55 0.18 150);
  --warning: oklch(0.65 0.16 85);
  --error: oklch(0.55 0.2 30);
  --surface: oklch(0.98 0.002 160);
  --surface-hover: oklch(0.96 0.005 160);
  --surface-elevated: oklch(1 0 0);
  --ink-muted: oklch(0.48 0.012 160);
  --accent-hover: oklch(0.48 0.18 165);
  --accent-subtle: oklch(0.92 0.04 160);
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: oklch(0.025 0.003 160);
    --foreground: oklch(0.93 0.006 160);
    --card: oklch(0.09 0.005 160);
    --card-foreground: oklch(0.93 0.006 160);
    --primary: oklch(0.6 0.18 165);
    --primary-foreground: oklch(0.025 0.003 160);
    --secondary: oklch(0.12 0.008 160);
    --secondary-foreground: oklch(0.78 0.006 160);
    --muted: oklch(0.12 0.005 160);
    --muted-foreground: oklch(0.55 0.012 160);
    --accent: oklch(0.6 0.18 165);
    --accent-foreground: oklch(0.025 0.003 160);
    --destructive: oklch(0.55 0.2 30);
    --destructive-foreground: oklch(0.025 0.003 160);
    --border: oklch(0.18 0.008 160);
    --input: oklch(0.18 0.008 160);
    --ring: oklch(0.6 0.18 165);
    --success: oklch(0.55 0.18 150);
    --warning: oklch(0.65 0.16 85);
    --error: oklch(0.55 0.2 30);
    --surface: oklch(0.09 0.005 160);
    --surface-hover: oklch(0.12 0.008 160);
    --surface-elevated: oklch(0.14 0.008 160);
    --ink-muted: oklch(0.55 0.012 160);
    --accent-hover: oklch(0.48 0.18 165);
    --accent-subtle: oklch(0.14 0.04 160);
  }
}

@layer base {
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  html {
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
    font-family: "Inter", system-ui, sans-serif;
    background: var(--background);
    color: var(--foreground);
    line-height: 1.6;
    min-height: 100vh;
    overflow-x: hidden;
  }

  #root {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
  }

  ::selection {
    background: var(--accent-subtle);
    color: var(--foreground);
  }

  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}



.card-header-accent {
  position: relative;
  overflow: hidden;
  transition: background-color 150ms ease;
}
.card-header-accent:hover {
  background-color: var(--surface-hover);
}
.card-header-accent::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 3px;
  height: 100%;
  background: var(--primary);
  border-radius: 0 2px 2px 0;
  transform: scaleY(0);
  transform-origin: top center;
  animation: accent-grow 400ms cubic-bezier(0.25, 1, 0.5, 1) 50ms forwards;
}
.card-header-accent:hover::before {
  width: 4px;
  transition: width 150ms ease;
}
@keyframes accent-grow {
  to { transform: scaleY(1); }
}
@media (prefers-reduced-motion: reduce) {
  .card-header-accent::before {
    animation: none;
    transform: scaleY(1);
  }
}

.profile-card-entrance {
  animation: pce-card 300ms cubic-bezier(0.22, 1, 0.36, 1) both;
}
.profile-card-entrance .avatar {
  animation: pce-avatar 450ms cubic-bezier(0.25, 1, 0.5, 1) both;
}
.profile-card-entrance .name-group {
  animation: pce-text 250ms cubic-bezier(0.25, 1, 0.5, 1) 180ms both;
}
.profile-card-entrance .id-group {
  animation: pce-id 200ms cubic-bezier(0.25, 1, 0.5, 1) 280ms both;
}
@keyframes pce-card { from { opacity: 0; transform: scale(0.96); } to { opacity: 1; transform: scale(1); } }
@keyframes pce-avatar { 0% { opacity: 0; transform: scale(0); box-shadow: 0 0 0 0 var(--primary); } 40% { opacity: 1; transform: scale(1.08); box-shadow: 0 0 0 8px color-mix(in oklch, var(--primary) 15%, transparent); } 100% { opacity: 1; transform: scale(1); box-shadow: 0 0 0 0 var(--primary); } }
@keyframes pce-text { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
@keyframes pce-id { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

import { useState } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "./ui/card"
import { Button } from "./ui/button"
import { Input } from "./ui/input"
import { Label } from "./ui/label"
import { deposit } from "@/actions/account.actions"
import type { IWalletTransaction, TBankAccountNumber } from "@/types"

const formatCurrency = (value: number | string) =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(Number(value))

export default function AddMoney({
  accounts,
  userId,
  onDeposit,
}: {
  accounts: { id: string; name: string; accountNumber: TBankAccountNumber; balance: number }[]
  userId: string
  onDeposit?: () => void
}) {
  const [accountNumber, setAccountNumber] = useState<TBankAccountNumber | undefined>(
    accounts.length > 0 ? accounts[0]!.accountNumber : undefined,
  )
  const [amount, setAmount] = useState("")
  const [depositing, setDepositing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState<IWalletTransaction | null>(null)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!accountNumber || !amount.trim()) return

    setDepositing(true)
    setError(null)
    setSuccess(null)

    try {
      const res = await deposit({
        userId,
        accountNumber,
        amount: Number.parseFloat(amount),
      })
      if (!res.ok) throw new Error(res.error ?? "Failed to deposit funds")
      setSuccess(res.data)
      setAmount(res.data.balance.toString())
      onDeposit?.()
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to deposit funds")
    } finally {
      setDepositing(false)
    }
  }

  return (
    <Card id="deposit-section">
      <CardHeader className="card-header-accent">
        <CardTitle>Add Money</CardTitle>
      </CardHeader>
      <CardContent>
        {success ? (
          <div className="space-y-4">
            <div className="rounded-lg bg-success/15 p-5 text-center space-y-1">
              <p className="text-sm font-semibold text-success">Deposit completed</p>
              <p className="text-lg font-mono font-bold text-foreground">
                {formatCurrency(success.balance)}
              </p>
              <p className="text-xs text-muted-foreground">{success.name}</p>
            </div>
            <Button variant="outline" size="sm" className="w-full" onClick={() => setSuccess(null)}>
              Deposit again
            </Button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-1.5">
              <Label htmlFor="addmoney-account">Into</Label>
              <select
                id="addmoney-account"
                value={accountNumber as unknown as string}
                onChange={(e) => setAccountNumber(e.target.value as unknown as TBankAccountNumber)}
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                required
              >
                <option value="" disabled>Select an account</option>
                {accounts.map((acc) => (
                  <option key={acc.id} value={acc.accountNumber as unknown as number}>
                    {acc.name} ({String(acc.accountNumber)}) · {formatCurrency(acc.balance)}
                  </option>
                ))}
              </select>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="addmoney-amount">Amount (USD)</Label>
              <Input
                id="addmoney-amount"
                type="number"
                step="0.01"
                min="0.01"
                placeholder="0.00"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
              />
            </div>
            {error && (
              <p className="text-sm text-destructive">{error}</p>
            )}
            <Button
              type="submit"
              disabled={!accountNumber}
              className="w-full"
            >
              {depositing ? "Processing..." : "Add Money"}
            </Button>
          </form>
        )}
      </CardContent>

      {depositing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm animate-fade-in">
          <div className="bg-card px-10 py-9 text-center space-y-6 max-w-sm w-full mx-4 rounded-xl shadow-xl">
            <div className="w-10 h-10 mx-auto rounded-full border-2 border-primary/30 flex items-center justify-center">
              <div className="w-5 h-5 rounded-full border-2 border-primary border-t-transparent animate-a-spin" />
            </div>
            <div className="space-y-1">
              <p className="text-2xl font-mono font-bold text-foreground tracking-tight">
                {formatCurrency(amount)}
              </p>
              <p className="text-sm text-muted-foreground">
                {accounts.find((a) => a.accountNumber === accountNumber)?.name ?? "Account"}
              </p>
            </div>
            <p className="text-xs text-muted-foreground/70">Processing deposit</p>
          </div>
        </div>
      )}
    </Card>
  )
}

